const config = $input.first().json;
const webhook = String(config.discordWebhookUrl ?? '');
const validWebhook = /^https:\/\/discord(?:app)?\.com\/api\/webhooks\/\d+\/[A-Za-z0-9._-]+$/.test(webhook);

if (!validWebhook) {
  throw new Error('Configure a valid Discord webhook URL in the Configure monitor node before running this workflow.');
}

return [{ json: config }];

const config = $input.first().json;
return [{
  json: {
    ...config,
    targetName: 'Website',
    targetUrl: 'https://scribeto.ai/',
    targetKind: 'page',
    startedAtMs: Date.now(),
  },
}];

const raw = $input.first().json;
const context = $('Prepare website check').first().json;
const responseTimeMs = Math.max(0, Date.now() - Number(context.startedAtMs));
const httpStatus = Number(raw.statusCode ?? raw.status ?? 0) || null;
const transportError = raw.error?.message ?? raw.error ?? (httpStatus === null ? raw.message : null);
const httpHealthy = !transportError && httpStatus !== null && httpStatus >= 200 && httpStatus < 300;
const status = !httpHealthy
  ? 'down'
  : responseTimeMs > Number(context.slowResponseThresholdMs)
    ? 'degraded'
    : 'healthy';

return [{
  json: {
    targetName: context.targetName,
    targetUrl: context.targetUrl,
    targetKind: context.targetKind,
    status,
    httpStatus,
    responseTimeMs,
    error: transportError ? String(transportError) : (httpHealthy ? null : `HTTP ${httpStatus ?? 'unknown'}`),
  },
}];

const config = $input.first().json;
return [{
  json: {
    ...config,
    targetName: 'Pricing page',
    targetUrl: 'https://scribeto.ai/pricing',
    targetKind: 'page',
    startedAtMs: Date.now(),
  },
}];

const raw = $input.first().json;
const context = $('Prepare pricing check').first().json;
const responseTimeMs = Math.max(0, Date.now() - Number(context.startedAtMs));
const httpStatus = Number(raw.statusCode ?? raw.status ?? 0) || null;
const transportError = raw.error?.message ?? raw.error ?? (httpStatus === null ? raw.message : null);
const httpHealthy = !transportError && httpStatus !== null && httpStatus >= 200 && httpStatus < 300;
const status = !httpHealthy
  ? 'down'
  : responseTimeMs > Number(context.slowResponseThresholdMs)
    ? 'degraded'
    : 'healthy';

return [{
  json: {
    targetName: context.targetName,
    targetUrl: context.targetUrl,
    targetKind: context.targetKind,
    status,
    httpStatus,
    responseTimeMs,
    error: transportError ? String(transportError) : (httpHealthy ? null : `HTTP ${httpStatus ?? 'unknown'}`),
  },
}];

const checks = $input.all().map((item) => item.json);
const context = $('Configure monitor').first().json;
const checkedAt = new Date().toISOString();
const severity = { healthy: 0, degraded: 1, down: 2 };
const overallStatus = checks.reduce(
  (worst, check) => severity[check.status] > severity[worst] ? check.status : worst,
  'healthy',
);

let eventType = null;
let stateChanged = false;
let incidentStartedAt = null;
let incidentDurationMs = null;
let previousStatus = null;

if (context.runMode === 'manual') {
  eventType = 'test';
} else {
  const state = $getWorkflowStaticData('global');
  previousStatus = state.lastStatus ?? null;
  incidentStartedAt = state.incidentStartedAt ?? null;

  if (previousStatus === null) {
    if (overallStatus !== 'healthy') {
      eventType = 'incident';
      stateChanged = true;
      incidentStartedAt = checkedAt;
    }
  } else if (previousStatus !== overallStatus) {
    stateChanged = true;
    if (previousStatus === 'healthy' && overallStatus !== 'healthy') {
      eventType = 'incident';
      incidentStartedAt = checkedAt;
    } else if (previousStatus === 'degraded' && overallStatus === 'down') {
      eventType = 'escalation';
    } else if (previousStatus === 'down' && overallStatus === 'degraded') {
      eventType = 'improvement';
    } else if (overallStatus === 'healthy') {
      eventType = 'recovery';
      if (incidentStartedAt) {
        incidentDurationMs = Date.parse(checkedAt) - Date.parse(incidentStartedAt);
      }
    }
  }

  state.lastStatus = overallStatus;
  state.lastCheckedAt = checkedAt;
  state.incidentStartedAt = overallStatus === 'healthy' ? null : (incidentStartedAt ?? checkedAt);
}
return [{
  json: {
    service: context.serviceName,
    website: context.websiteUrl,
    runMode: context.runMode,
    overallStatus,
    checkedAt,
    previousStatus,
    stateChanged,
    eventType,
    shouldNotify: eventType !== null,
    incidentStartedAt,
    incidentDurationMs,
    checks,
  },
}];

const report = $input.first().json;
const presentation = {
  test: { title: 'ScribeTo monitor test', color: 3447003 },
  incident: { title: 'ScribeTo incident detected', color: 15158332 },
  escalation: { title: 'ScribeTo incident escalated', color: 10038562 },
  improvement: { title: 'ScribeTo incident improving', color: 15844367 },
  recovery: { title: 'ScribeTo service recovered', color: 3066993 },
}[report.eventType];

const icon = { healthy: 'OK', degraded: 'SLOW', down: 'DOWN' };
const checkLines = report.checks.map((check) => {
  const http = check.httpStatus ?? 'no status';
  const detail = check.error ? ` - ${check.error}` : '';
  return `**${icon[check.status]} ${check.targetName}:** ${check.status} | HTTP ${http} | ${check.responseTimeMs} ms${detail}`;
});
const duration = report.incidentDurationMs === null
  ? null
  : `${Math.max(1, Math.round(report.incidentDurationMs / 60000))} minute(s)`;
const fields = [
  { name: 'Overall status', value: report.overallStatus.toUpperCase(), inline: true },
  { name: 'Run mode', value: report.runMode, inline: true },
  { name: 'Endpoint checks', value: checkLines.join('\n').slice(0, 1024), inline: false },
];
if (duration) fields.push({ name: 'Incident duration', value: duration, inline: true });

const embed = {
  title: presentation.title,
  url: report.website,
  color: presentation.color,
  description: `State-aware uptime result for [ScribeTo](${report.website}).`,
  fields,
  timestamp: report.checkedAt,
  footer: { text: 'ScribeTo public uptime monitor via n8n' },
};

return [{ json: { ...report, discordPayload: { embeds: [embed] } } }];

const source = $('Build Discord embed').first().json;
const response = $input.first().json;
const httpStatus = Number(response.statusCode ?? response.status ?? 0) || null;
const rawError = response.error?.message ?? response.error ?? null;
const notificationSent = !rawError && httpStatus !== null && httpStatus >= 200 && httpStatus < 300;
const { discordPayload, ...report } = source;
return [{
  json: {
    ...report,
    notificationAttempted: true,
    notificationSent,
    notificationHttpStatus: httpStatus,
    notificationError: rawError ? String(rawError) : (notificationSent ? null : `HTTP ${httpStatus ?? 'unknown'}`),
  },
}];

const report = $input.first().json;
return [{
  json: {
    ...report,
    notificationAttempted: false,
    notificationSent: false,
    notificationHttpStatus: null,
    notificationError: null,
  },
}];
